    creatinine_value = None
    is_abnormal = False

    # Pattern 1: "creatinine was [value] mg/dL"
    m = re.search(r'creatinine(?:\s+(?:was|is|of))?\s+([\d.]+)\s*mg/dL', section, re.IGNORECASE)
    if m:
        try:
            creatinine_value = float(m.group(1))
        except:
            pass

    # Pattern 2: "creatinine of [value] mg/dL"
    if creatinine_value is None:
        m = re.search(r'creatinine\s+of\s+([\d.]+)\s*mg/dL', section, re.IGNORECASE)
        if m:
            try:
                creatinine_value = float(m.group(1))
            except:
                pass

    # Pattern 3: "CRE was [value]" or "CRE at [value]"
    if creatinine_value is None:
        m = re.search(r'CRE\s+(?:was|at|of)\s+([\d.]+)', section, re.IGNORECASE)
        if m:
            try:
                creatinine_value = float(m.group(1))
            except:
                pass

    # Determine if abnormal (normal range is typically 0.6-1.2 mg/dL for adults)
    # Values outside this range are considered abnormal
    if creatinine_value is not None:
        if creatinine_value < 0.6 or creatinine_value > 1.2:
            is_abnormal = True

    creatinine_results.append({
        'patient_id': patient_id,
        'creatinine_value': creatinine_value,
        'is_abnormal': is_abnormal
    })

print(f"Total creatinine results extracted: {len(creatinine_results)}")
