import re
import json
from datetime import date

# Read the full Patient.md file
with open('doc/Patient.md', 'r') as f:
    content = f.read()

# Split into individual patient sections
sections = re.split(r'\n\n(?=The|For|Regarding|Patient|The file|The summary|The health|Turning to|Finally)', content)

patients = {}

for section in sections:
    # Extract patient ID
    mrn_match = re.search(r'(?:Medical Record Number|file number|patient)\s+(\d+)', section, re.IGNORECASE)
    if not mrn_match:
        continue

    mrn = mrn_match.group(1)

    # Extract birthdate - look for various patterns
    birthdate_str = ""

    # Pattern 1: "born on [date]"
    m = re.search(r'born on\s+(.+?)(?:\.|\n|$)', section, re.IGNORECASE)
    if m:
        birthdate_str = m.group(1).strip()

    # Pattern 2: "birthday on [date]"
    if not birthdate_str:
        m = re.search(r'birthday on\s+(.+?)(?:\.|\n|$)', section, re.IGNORECASE)
        if m:
            birthdate_str = m.group(1).strip()

    # Pattern 3: "birthdate is [date]"
    if not birthdate_str:
        m = re.search(r'birthdate is\s+(.+?)(?:\.|\n|$)', section, re.IGNORECASE)
        if m:
            birthdate_str = m.group(1).strip()

    # Pattern 4: "date of birth is [date]"
    if not birthdate_str:
        m = re.search(r'date of birth (?:is|recorded as)\s+(.+?)(?:\.|\n|$)', section, re.IGNORECASE)
        if m:
            birthdate_str = m.group(1).strip()

    # Pattern 5: "born in [year]"
    if not birthdate_str:
        m = re.search(r'born in\s+(.+?)(?:\.|\n|$)', section, re.IGNORECASE)
        if m:
            birthdate_str = m.group(1).strip()

    # Pattern 6: "birth year"
    if not birthdate_str:
        m = re.search(r'birth year\s+(?:as\s+)?(\d{4})', section, re.IGNORECASE)
        if m:
            birthdate_str = m.group(1)

    # Pattern 7: "registered as.*?born"
    if not birthdate_str:
        m = re.search(r'registered as.*?born on\s+(.+?)(?:\.|\n|$)', section, re.IGNORECASE | re.DOTALL)
        if m:
            birthdate_str = m.group(1).strip()

    # Parse birthdate to calculate age
    birth_date = None
    if birthdate_str:
        # Try to parse various formats
        # Format: "July 13th, 1944" or "May 22nd, 1961" or "January 28th, 1958"
        # Also: "late February of 1948", "the middle of the year 1962, on the eighth of June"

        # Extract year first
        year_match = re.search(r'(\d{4})', birthdate_str)
        if year_match:
            year = int(year_match.group(1))

            # Try to extract month and day
            month_day_match = re.search(r'(january|february|march|april|may|june|july|august|september|october|november|december)\s+(\d+)(?:st|nd|rd|th)?', birthdate_str, re.IGNORECASE)
            if month_day_match:
                month_name = month_day_match.group(1).lower()
                day = int(month_day_match.group(2))

                months = {'january': 1, 'february': 2, 'march': 3, 'april': 4, 'may': 5, 'june': 6,
                         'july': 7, 'august': 8, 'september': 9, 'october': 10, 'november': 11, 'december': 12}
                month = months.get(month_name)
                if month:
                    try:
                        birth_date = date(year, month, day)
                    except:
                        pass

            # If we only have year, use Jan 1 as default
            elif year:
                try:
                    birth_date = date(year, 1, 1)
                except:
                    pass

    # Calculate age as of reference date (let's use Dec 31, 1998 as end of study period)
    reference_date = date(1998, 12, 31)
    age = None
    if birth_date:
        age = reference_date.year - birth_date.year
        if (reference_date.month, reference_date.day) < (birth_date.month, birth_date.day):
            age -= 1

    patients[mrn] = {
        'mrn': mrn,
        'birthdate_raw': birthdate_str,
        'birth_date': birth_date,
        'age': age
    }

print(f"Total patients extracted: {len(patients)}")
print("\nFirst 10 patients:")
for i, (mrn, p) in enumerate(list(patients.items())[:10]):
    print(f"MRN: {mrn}, Age: {p['age']}, Birthdate: {p['birthdate_raw']}")
